description:
[
  {
    "topic": "Front-end Treasury repricing (2Y yield surge / Fed cut odds)",
    "why_gold_cares": "Higher short-end real rates raise the opportunity cost of holding non-yielding gold and support the dollar",
    "impact_threshold": "Double-digit bps daily moves in 2Y or a visible shift in near-term Fed cut probabilities",
    "directional_risk": "BEARISH_GOLD"
  },
  {
    "topic": "Fed speakers / FOMC communication",
    "why_gold_cares": "Guidance on the cut path resets real yield expectations, the dominant gold discount factor",
    "impact_threshold": "Explicit pushback on near-term cuts, or a policymaker flagging inflation reacceleration",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "US ISM manufacturing PMI and prices-paid component",
    "why_gold_cares": "Growth/inflation mix drives yields and DXY within minutes of release; prices-paid feeds inflation expectations",
    "impact_threshold": "Sizeable surprise versus consensus, especially divergence between headline and prices-paid",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Payrolls week data cluster (JOLTS, ADP, claims, NFP)",
    "why_gold_cares": "Labor data is the primary input for the Fed path; weak prints ease real yields and lift gold",
    "impact_threshold": "Consensus misses large enough to move 2Y yields and rate-cut pricing",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "US dollar index momentum",
    "why_gold_cares": "Gold is dollar-denominated; sustained DXY strength mechanically compresses gold bids",
    "impact_threshold": "Broad-based intraday DXY trend extension rather than noise, confirmed by EUR and JPY legs",
    "directional_risk": "BEARISH_GOLD"
  },
  {
    "topic": "Geopolitical de-escalation or escalation headlines (ceasefire, sanctions, strikes)",
    "why_gold_cares": "Safe-haven premium is added or unwound quickly with no data lag",
    "impact_threshold": "Official confirmation from governments/state media rather than unnamed-source reports",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Central bank gold demand and official reserve updates",
    "why_gold_cares": "Structural bid underpins dips; slowdown removes a key support pillar after a parabolic advance",
    "impact_threshold": "Monthly reserve reports or credible reports of pause/acceleration in official buying",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "ETF flows, CME margin changes and positioning liquidation",
    "why_gold_cares": "After large price extensions, margin hikes and ETF redemptions force mechanical selling and momentum unwinds",
    "impact_threshold": "Exchange margin notices or multi-session outflow streaks in major gold ETFs",
    "directional_risk": "BEARISH_GOLD"
  }
]
